class Solution {
public:
    int maxScore(vector<int>& parent, vector<int>& op, vector<int>& score) {
        int n = parent.size();
        vector<vector<int>> child(n);
        for (int i = 1; i < n; ++i) {
            child[parent[i]].push_back(i);
        }

        // iterative preorder to obtain processing order
        vector<int> order;
        order.reserve(n);
        vector<int> stk;
        stk.push_back(0);
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : child[u]) stk.push_back(v);
        }

        vector<long long> dp(n, 0);
        for (int idx = (int)order.size() - 1; idx >= 0; --idx) {
            int u = order[idx];
            long long total = score[u];
            for (int v : child[u]) total += dp[v];

            if (!child[u].empty()) {
                long long minChild = LLONG_MAX;
                for (int v : child[u]) {
                    if (dp[v] < minChild) minChild = dp[v];
                }
                if (op[u] == 1) {               // must erase exactly one child
                    total -= minChild;
                } else {                         // optional erase
                    if (minChild < 0) total -= minChild;
                }
            }
            dp[u] = total;
        }
        return (int)dp[0];
    }
};
